type Key = keyof (typeof dict)['en'];

const STORAGE_KEY = 'merchant.locale';

const RTL_LOCALES: ReadonlySet<string> = new Set(['ar']);

function applyPlatformRTL(locale: Locale) {
  const rtl = RTL_LOCALES.has(locale);
  try {
    if (typeof document !== 'undefined') {
      document.documentElement.setAttribute('dir', rtl ? 'rtl' : 'ltr');
    }
  } catch {
    /* non-DOM environment */
  }
}

let current: Locale = 'en';
try {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved === 'sw' || saved === 'en' || saved === 'ar') current = saved;
} catch {
  /* storage unavailable */
}

const listeners = new Set<() => void>();

export function setLocale(locale: Locale) {
  current = locale;
  try {
    localStorage.setItem(STORAGE_KEY, locale);
  } catch {
    /* ignore */
  }
  applyPlatformRTL(locale);
  listeners.forEach((l) => l());
}

export function getLocale(): Locale {
  return current;
}

export function onLocaleChange(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function t(key: Key, params?: Record<string, string | number>): string {
  let s: string = dict[current][key] ?? dict.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      s = s.replace(`{${k}}`, String(v));
    }
  }
  return s;
}

export type { Key as I18nKey };

/* ---------- Money / currency ---------- */

export const CURRENCIES: Record<string, { symbol: string; decimals: number }> = {
  TZS: { symbol: 'TZS ', decimals: 0 },
};

export function formatMoney(n: number, currency: string = 'TZS'): string {
  const c = CURRENCIES[currency] ?? CURRENCIES.TZS;
  return `${c.symbol}${Math.round(n).toLocaleString('en-US')}`;
}
